from __future__ import annotations

"""Decide how the bot reacts to normalized webhook events.

The router hands us a flat list of :class:`NormalizedEvent` objects. For each
one we decide whether the bot should send a reply and, if so, what text. The
handler keeps a small in-memory log of replies keyed by recipient so a test (or
an operator tailing logs) can see exactly who we answered and how many times.

The reply text is intentionally trivial: this challenge is about *when* we reply,
not about natural language. A genuine inbound text gets an echo-style
acknowledgement; a postback gets a payload-aware line.
"""

from dataclasses import dataclass

from webhook_router import (
    KIND_MESSAGE,
    KIND_POSTBACK,
    NormalizedEvent,
    is_user_text,
)


@dataclass
class Reply:
    """A reply the bot intends to send back to a sender."""

    recipient_id: str
    text: str


def compose_reply(event: NormalizedEvent) -> str:
    """Build the reply text for an event we have decided to answer."""

    if event.kind == KIND_POSTBACK:
        payload = event.payload or event.text or ""
        return f"Got your selection: {payload}".strip()
    body = event.text or ""
    return f"You said: {body}".strip()


def should_reply(event: NormalizedEvent) -> bool:
    """Return whether this event should produce an outbound bot reply.

    A reply only makes sense for an event that actually carries something the
    user typed or tapped. Receipts and empty events never get a reply.
    """

    if event.kind not in (KIND_MESSAGE, KIND_POSTBACK):
        return False
    if not is_user_text(event):
        return False
    return True


class BotHandler:
    """Stateful handler that turns events into replies and logs them."""

    def __init__(self) -> None:
        # recipient_id -> list of reply texts we sent to that recipient
        self._reply_log: dict[str, list[str]] = {}
        self._seen = 0

    def handle_event(self, event: NormalizedEvent) -> Reply | None:
        """Process one event, recording and returning a reply if we made one."""

        self._seen += 1
        if not should_reply(event):
            return None
        reply = Reply(recipient_id=event.sender_id, text=compose_reply(event))
        self._reply_log.setdefault(reply.recipient_id, []).append(reply.text)
        return reply

    def handle_events(self, events: list[NormalizedEvent]) -> list[Reply]:
        """Process a batch of events, returning the replies actually sent."""

        replies: list[Reply] = []
        for event in events:
            reply = self.handle_event(event)
            if reply is not None:
                replies.append(reply)
        return replies

    def replies_to(self, recipient_id: str) -> list[str]:
        """Return the reply texts sent to a given recipient, in order."""

        return list(self._reply_log.get(recipient_id, []))

    def reply_count(self, recipient_id: str) -> int:
        """How many replies were sent to a given recipient."""

        return len(self._reply_log.get(recipient_id, []))

    def total_replies(self) -> int:
        """Total replies sent across every recipient."""

        return sum(len(texts) for texts in self._reply_log.values())

    def events_seen(self) -> int:
        """How many events have passed through the handler."""

        return self._seen


def process_webhook(handler: BotHandler, events: list[NormalizedEvent]) -> list[Reply]:
    """Convenience entry point: feed normalized events through a handler."""

    return handler.handle_events(events)

