from __future__ import annotations

"""Parse and classify raw Messenger Platform webhook payloads.

A webhook callback POSTs a JSON body shaped roughly like::

    {
        "object": "page",
        "entry": [
            {
                "id": "<page-id>",
                "time": 1700000000000,
                "messaging": [ {<event>}, ... ]
            },
            ...
        ]
    }

Each element of ``entry[]`` carries an array of per-recipient events. Most of
the time those events live under ``messaging``. Under the handover protocol,
when this app is the secondary receiver, the platform delivers events under a
``standby`` array on the same entry instead.

This module flattens that nested structure into a flat list of
:class:`NormalizedEvent` records and tags each one with a coarse event kind so
downstream code can decide what to do with it. It does not decide anything about
replies itself — it only reshapes and labels.
"""

from dataclasses import dataclass, field
from typing import Any


# Event kinds we tag while flattening. These are descriptive labels only.
KIND_MESSAGE = "message"
KIND_POSTBACK = "postback"
KIND_DELIVERY = "delivery"
KIND_READ = "read"
KIND_OTHER = "other"


@dataclass
class NormalizedEvent:
    """One flattened webhook event with the context needed to handle it."""

    channel: str  # which array it arrived on: "messaging" or "standby"
    kind: str
    sender_id: str
    recipient_id: str
    timestamp: int
    text: str | None = None
    payload: str | None = None
    is_echo: bool = False
    app_id: int | None = None
    raw: dict = field(default_factory=dict)


def _as_int(value: Any) -> int:
    """Best-effort coercion of a millisecond timestamp to int."""

    try:
        return int(value)
    except (TypeError, ValueError):
        return 0


def _str_or_none(value: Any) -> str | None:
    if value is None:
        return None
    return str(value)


def _classify(event: dict) -> str:
    """Return the coarse kind label for a single raw event dict."""

    if "message" in event and isinstance(event.get("message"), dict):
        return KIND_MESSAGE
    if "postback" in event and isinstance(event.get("postback"), dict):
        return KIND_POSTBACK
    if "delivery" in event:
        return KIND_DELIVERY
    if "read" in event:
        return KIND_READ
    return KIND_OTHER


def _normalize_event(event: dict, channel: str) -> NormalizedEvent:
    """Turn one raw event dict into a :class:`NormalizedEvent`."""

    sender = event.get("sender") or {}
    recipient = event.get("recipient") or {}
    message = event.get("message") if isinstance(event.get("message"), dict) else {}
    postback = event.get("postback") if isinstance(event.get("postback"), dict) else {}

    text = None
    app_id = None
    is_echo = False
    if message:
        text = _str_or_none(message.get("text"))
        is_echo = bool(message.get("is_echo", False))
        app_id = message.get("app_id")

    payload = None
    if postback:
        payload = _str_or_none(postback.get("payload"))
        if text is None:
            text = _str_or_none(postback.get("title"))

    return NormalizedEvent(
        channel=channel,
        kind=_classify(event),
        sender_id=str(sender.get("id", "")),
        recipient_id=str(recipient.get("id", "")),
        timestamp=_as_int(event.get("timestamp")),
        text=text,
        payload=payload,
        is_echo=is_echo,
        app_id=app_id,
        raw=event,
    )


def normalize_payload(body: Any) -> list[NormalizedEvent]:
    """Flatten a raw webhook body into a list of normalized events.

    Tolerates missing keys, wrong types, and empty arrays — a malformed entry
    simply contributes no events rather than raising.
    """

    if not isinstance(body, dict):
        return []

    entries = body.get("entry")
    if not isinstance(entries, list):
        return []

    events: list[NormalizedEvent] = []
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        for channel in ("messaging", "standby"):
            raw_events = entry.get(channel)
            if not isinstance(raw_events, list):
                continue
            for raw_event in raw_events:
                if not isinstance(raw_event, dict):
                    continue
                events.append(_normalize_event(raw_event, channel))
    return events


def is_user_text(event: NormalizedEvent) -> bool:
    """True when the event carries actual text or a postback payload."""

    if event.kind == KIND_MESSAGE:
        return bool(event.text)
    if event.kind == KIND_POSTBACK:
        return bool(event.payload) or bool(event.text)
    return False

