from __future__ import annotations

from bot_handler import (
    BotHandler,
    compose_reply,
    process_webhook,
    should_reply,
)
from webhook_router import (
    KIND_DELIVERY,
    KIND_MESSAGE,
    KIND_READ,
    NormalizedEvent,
    is_user_text,
    normalize_payload,
)


# --- payload builders -------------------------------------------------------

def user_message_payload(sender="USER1", recipient="PAGE", text="hello", ts=1000):
    return {
        "object": "page",
        "entry": [
            {
                "id": recipient,
                "time": ts,
                "messaging": [
                    {
                        "sender": {"id": sender},
                        "recipient": {"id": recipient},
                        "timestamp": ts,
                        "message": {"mid": "m.1", "text": text},
                    }
                ],
            }
        ],
    }


def echo_payload(page="PAGE", user="USER1", text="You said: hello", ts=1001):
    # When the Page sends a message, Messenger echoes it back to the webhook.
    # sender is the Page, recipient is the user, and the message is flagged.
    return {
        "object": "page",
        "entry": [
            {
                "id": page,
                "time": ts,
                "messaging": [
                    {
                        "sender": {"id": page},
                        "recipient": {"id": user},
                        "timestamp": ts,
                        "message": {
                            "mid": "m.echo.1",
                            "text": text,
                            "is_echo": True,
                            "app_id": 123456789,
                        },
                    }
                ],
            }
        ],
    }


def standby_payload(sender="USER2", recipient="PAGE", text="hi there", ts=2000):
    # Handover protocol: this app is the secondary receiver, so the event
    # arrives under standby instead of messaging.
    return {
        "object": "page",
        "entry": [
            {
                "id": recipient,
                "time": ts,
                "standby": [
                    {
                        "sender": {"id": sender},
                        "recipient": {"id": recipient},
                        "timestamp": ts,
                        "message": {"mid": "m.sb.1", "text": text},
                    }
                ],
            }
        ],
    }


def delivery_payload(sender="USER1", recipient="PAGE", ts=3000):
    return {
        "object": "page",
        "entry": [
            {
                "id": recipient,
                "time": ts,
                "messaging": [
                    {
                        "sender": {"id": sender},
                        "recipient": {"id": recipient},
                        "timestamp": ts,
                        "delivery": {"mids": ["m.1"], "watermark": ts},
                    }
                ],
            }
        ],
    }


def read_payload(sender="USER1", recipient="PAGE", ts=4000):
    return {
        "object": "page",
        "entry": [
            {
                "id": recipient,
                "time": ts,
                "messaging": [
                    {
                        "sender": {"id": sender},
                        "recipient": {"id": recipient},
                        "timestamp": ts,
                        "read": {"watermark": ts},
                    }
                ],
            }
        ],
    }


# --- happy path -------------------------------------------------------------

def test_genuine_user_message_gets_exactly_one_reply():
    events = normalize_payload(user_message_payload(text="hello"))
    handler = BotHandler()
    replies = process_webhook(handler, events)
    assert len(replies) == 1
    assert replies[0].recipient_id == "USER1"
    assert "hello" in replies[0].text
    assert handler.reply_count("USER1") == 1


# --- the loop bug: echoes of the bot's own message must not be answered -----

def test_page_echo_produces_no_reply():
    events = normalize_payload(echo_payload(text="You said: hello"))
    handler = BotHandler()
    replies = process_webhook(handler, events)
    assert replies == []
    assert handler.total_replies() == 0


def test_real_message_then_echo_does_not_loop():
    # A user sends a message (one reply), then the Page echo of that reply
    # must not trigger another reply back to anyone.
    handler = BotHandler()
    process_webhook(handler, normalize_payload(user_message_payload(text="hello")))
    process_webhook(handler, normalize_payload(echo_payload(text="You said: hello")))
    # Exactly one reply total: the original answer to the user.
    assert handler.total_replies() == 1
    assert handler.reply_count("USER1") == 1
    assert handler.reply_count("PAGE") == 0


# --- standby (handover) events must not be answered -------------------------

def test_standby_event_produces_no_reply():
    events = normalize_payload(standby_payload(text="hi there"))
    handler = BotHandler()
    replies = process_webhook(handler, events)
    assert replies == []
    assert handler.total_replies() == 0


def test_standby_channel_is_labeled_but_not_replied():
    events = normalize_payload(standby_payload())
    assert len(events) == 1
    assert events[0].channel == "standby"
    handler = BotHandler()
    assert handler.handle_event(events[0]) is None


# --- delivery / read receipts are non-reply events --------------------------

def test_delivery_receipt_produces_no_reply():
    events = normalize_payload(delivery_payload())
    assert events and events[0].kind == KIND_DELIVERY
    handler = BotHandler()
    assert process_webhook(handler, events) == []


def test_read_receipt_produces_no_reply():
    events = normalize_payload(read_payload())
    assert events and events[0].kind == KIND_READ
    handler = BotHandler()
    assert process_webhook(handler, events) == []


# --- boundary: empty text message should not produce a reply ----------------

def test_empty_text_message_is_not_replied():
    events = normalize_payload(user_message_payload(text=""))
    handler = BotHandler()
    assert process_webhook(handler, events) == []


# --- unexpected / malformed shapes must not crash ---------------------------

def test_malformed_payloads_do_not_crash():
    assert normalize_payload(None) == []
    assert normalize_payload({}) == []
    assert normalize_payload({"entry": "nope"}) == []
    assert normalize_payload({"entry": [None, 7, "x"]}) == []
    assert normalize_payload({"entry": [{"messaging": "bad"}]}) == []
    assert normalize_payload({"entry": [{"messaging": [None, 3]}]}) == []
    handler = BotHandler()
    assert process_webhook(handler, normalize_payload({"entry": [{}]})) == []


# --- mixed batch: only the real user message gets answered ------------------

def test_mixed_batch_only_answers_genuine_user_message():
    body = {
        "object": "page",
        "entry": [
            {
                "id": "PAGE",
                "time": 5000,
                "messaging": [
                    {
                        "sender": {"id": "PAGE"},
                        "recipient": {"id": "USER1"},
                        "timestamp": 5000,
                        "message": {"mid": "e", "text": "echo!", "is_echo": True, "app_id": 99},
                    },
                    {
                        "sender": {"id": "USER1"},
                        "recipient": {"id": "PAGE"},
                        "timestamp": 5001,
                        "message": {"mid": "u", "text": "real question"},
                    },
                    {
                        "sender": {"id": "USER1"},
                        "recipient": {"id": "PAGE"},
                        "timestamp": 5002,
                        "delivery": {"mids": ["u"], "watermark": 5002},
                    },
                ],
                "standby": [
                    {
                        "sender": {"id": "USER3"},
                        "recipient": {"id": "PAGE"},
                        "timestamp": 5003,
                        "message": {"mid": "sb", "text": "secondary"},
                    }
                ],
            }
        ],
    }
    handler = BotHandler()
    replies = process_webhook(handler, normalize_payload(body))
    assert len(replies) == 1
    assert replies[0].recipient_id == "USER1"
    assert "real question" in replies[0].text
    assert handler.total_replies() == 1


# --- should_reply / compose_reply behave for valid inbound text -------------

def test_should_reply_and_compose_for_plain_text():
    event = NormalizedEvent(
        channel="messaging",
        kind=KIND_MESSAGE,
        sender_id="USER1",
        recipient_id="PAGE",
        timestamp=1,
        text="ping",
    )
    assert is_user_text(event) is True
    assert should_reply(event) is True
    assert compose_reply(event) == "You said: ping"
